@Override
public Response toResponse(final JerseyViolationException exception) {
    logger.debug("jersey violation exception: " + (Helper.isEmpty(exception.getMessage()) ? "unknown reason" : exception.getMessage()));
    final Set<ConstraintViolation<?>> violations = exception.getConstraintViolations();
    final Invocable invocable = exception.getInvocable();
    final List<String> errors = exception.getConstraintViolations().stream().map(violation -> ConstraintMessage.getMessage(violation, invocable)).collect(Collectors.toList());
    final int status = ConstraintMessage.determineStatus(violations, invocable);
    return // PATH: Test should invoke the next Response.status(...) [step in execution path]
    Response.status(status).type(MediaType.APPLICATION_JSON).entity(new JsonErrorEntity(errors)).build();
}

