@Consumes(MediaType.APPLICATION_JSON)
@Produces(MediaType.APPLICATION_JSON)
public Response doPost(@NotNull
GHRequest request, @Context
HttpServletRequest httpReq) {
    StopWatch sw = new StopWatch().start();
    request = ghRequestTransformer.transformRequest(request);
    // throw a dedicated exception here, otherwise a missing profile is still caught in Router
    if (Helper.isEmpty(request.getProfile()) && (request.getCustomModel() != null)) {
        throw new IllegalArgumentException("The 'profile' parameter is required when you use the `custom_model` parameter");
    }
    PMap profileResolverHints = new PMap(request.getHints());
    profileResolverHints.putObject("profile", request.getProfile());
    profileResolverHints.putObject("has_curbsides", !request.getCurbsides().isEmpty());
    request.setProfile(profileResolver.resolveProfile(profileResolverHints));
    removeLegacyParameters(request.getHints());
    GHResponse ghResponse = graphHopper.route(request);
    boolean instructions = request.getHints().getBool(INSTRUCTIONS, true);
    boolean enableElevation = request.getHints().getBool("elevation", false);
    boolean calcPoints = request.getHints().getBool(CALC_POINTS, true);
    boolean pointsEncoded = request.getHints().getBool("points_encoded", true);
    double took = sw.stop().getMillisDouble();
    String infoStr = (((httpReq.getRemoteAddr() + " ") + httpReq.getLocale()) + " ") + httpReq.getHeader("User-Agent");
    String logStr = (((((((((infoStr + " ") + request.getPoints().size()) + ", took: ") + String.format("%.1f", took)) + " ms, algo: ") + request.getAlgorithm()) + ", profile: ") + request.getProfile()) + ", custom_model: ") + request.getCustomModel();
    if (ghResponse.hasErrors()) {
        throw new MultiException(ghResponse.getErrors());
    } else {
        logger.info(((((((((((((logStr + ", alternatives: ") + ghResponse.getAll().size()) + ", distance0: ") + ghResponse.getBest().getDistance()) + ", weight0: ") + ghResponse.getBest().getRouteWeight()) + ", time0: ") + Math.round(ghResponse.getBest().getTime() / 60000.0F)) + "min") + ", points0: ") + ghResponse.getBest().getPoints().size()) + ", debugInfo: ") + ghResponse.getDebugInfo());
        return // PATH: Test should invoke the next Response$ResponseBuilder.type(...) [step in execution path]
        Response.ok(ResponsePathSerializer.jsonObject(ghResponse, osmDate, instructions, calcPoints, enableElevation, pointsEncoded, took)).header("X-GH-Took", "" + Math.round(took)).type(MediaType.APPLICATION_JSON).build();
    }
}

