@GET
@Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML, "application/gpx+xml" })
public Response doGet(@Context
HttpServletRequest httpReq, @Context
UriInfo uriInfo, @QueryParam(WAY_POINT_MAX_DISTANCE)
@DefaultValue("1")
double minPathPrecision, @QueryParam(ELEVATION_WAY_POINT_MAX_DISTANCE)
Double minPathElevationPrecision, @QueryParam("point")
@NotNull
List<GHPointParam> pointParams, @QueryParam("type")
@DefaultValue("json")
String type, @QueryParam(INSTRUCTIONS)
@DefaultValue("true")
boolean instructions, @QueryParam(CALC_POINTS)
@DefaultValue("true")
boolean calcPoints, @QueryParam("elevation")
@DefaultValue("false")
boolean enableElevation, @QueryParam("points_encoded")
@DefaultValue("true")
boolean pointsEncoded, @QueryParam("profile")
String profileName, @QueryParam(ALGORITHM)
@DefaultValue("")
String algoStr, @QueryParam("locale")
@DefaultValue("en")
String localeStr, @QueryParam(POINT_HINT)
List<String> pointHints, @QueryParam(CURBSIDE)
List<String> curbsides, @QueryParam(SNAP_PREVENTION)
List<String> snapPreventions, @QueryParam(PATH_DETAILS)
List<String> pathDetails, @QueryParam("heading")
@NotNull
List<Double> headings, @QueryParam("gpx.route")
@DefaultValue("true")
boolean withRoute, /* default to false for the route part in next API version, see #437 */
@QueryParam("gpx.track")
@DefaultValue("true")
boolean withTrack, @QueryParam("gpx.waypoints")
@DefaultValue("false")
boolean withWayPoints, @QueryParam("gpx.trackname")
@DefaultValue("GraphHopper Track")
String trackName, @QueryParam("gpx.millis")
String timeString) {
    StopWatch sw = new StopWatch().start();
    List<GHPoint> points = pointParams.stream().map(AbstractParam::get).collect(toList());
    boolean writeGPX = "gpx".equalsIgnoreCase(type);
    instructions = writeGPX || instructions;
    if (enableElevation && (!hasElevation))
        throw new IllegalArgumentException("Elevation not supported!");

    GHRequest request = new GHRequest();
    initHints(request.getHints(), uriInfo.getQueryParameters());
    if (minPathElevationPrecision != null)
        request.getHints().putObject(ELEVATION_WAY_POINT_MAX_DISTANCE, minPathElevationPrecision);

    request.setPoints(points).setProfile(profileName).setAlgorithm(algoStr).setLocale(localeStr).setHeadings(headings).setPointHints(pointHints).setCurbsides(curbsides).setSnapPreventions(snapPreventions).setPathDetails(pathDetails).getHints().putObject(CALC_POINTS, calcPoints).putObject(INSTRUCTIONS, instructions).putObject(WAY_POINT_MAX_DISTANCE, minPathPrecision);
    request = ghRequestTransformer.transformRequest(request);
    PMap profileResolverHints = new PMap(request.getHints());
    profileResolverHints.putObject("profile", profileName);
    profileResolverHints.putObject("has_curbsides", !curbsides.isEmpty());
    profileName = profileResolver.resolveProfile(profileResolverHints);
    removeLegacyParameters(request.getHints());
    request.setProfile(profileName);
    GHResponse ghResponse = graphHopper.route(request);
    double took = sw.stop().getMillisDouble();
    String logStr = (((((((((((httpReq.getRemoteAddr() + " ") + httpReq.getLocale()) + " ") + httpReq.getHeader("User-Agent")) + " ") + points) + ", took: ") + String.format("%.1f", took)) + "ms, algo: ") + algoStr) + ", profile: ") + profileName;
    if (ghResponse.hasErrors()) {
        logger.info((logStr + " ") + ghResponse);
        return Response.status(Response.Status.BAD_REQUEST).entity(new MultiException(ghResponse.getErrors())).type(writeGPX ? "application/gpx+xml" : MediaType.APPLICATION_JSON).build();
    } else {
        logger.info(((((((((((((logStr + ", alternatives: ") + ghResponse.getAll().size()) + ", distance0: ") + ghResponse.getBest().getDistance()) + ", weight0: ") + ghResponse.getBest().getRouteWeight()) + ", time0: ") + Math.round(ghResponse.getBest().getTime() / 60000.0F)) + "min") + ", points0: ") + ghResponse.getBest().getPoints().size()) + ", debugInfo: ") + ghResponse.getDebugInfo());
        return writeGPX ? gpxSuccessResponseBuilder(ghResponse, timeString, trackName, enableElevation, withRoute, withTrack, withWayPoints, Constants.VERSION).header("X-GH-Took", "" + Math.round(took)).build() : Response.ok(ResponsePathSerializer.jsonObject(ghResponse, osmDate, instructions, calcPoints, enableElevation, pointsEncoded, took)).header("X-GH-Took", "" + Math.round(took)).type(MediaType.APPLICATION_JSON).build();
    }
}

