    environment.jersey().register(new AbstractBinder() {
        @Override
        protected void configure() {
            bind(configuration.getGraphHopperConfiguration()).to(GraphHopperConfig.class);
            bind(graphHopper).to(GraphHopper.class);
            bind(new JTSTriangulator(graphHopper.getRouterConfig())).to(Triangulator.class);
            bindFactory(GraphHopperBundle.MapMatchingRouterFactoryFactory.class).to(MapMatchingResource.MapMatchingRouterFactory.class);
            bindFactory(GraphHopperBundle.PathDetailsBuilderFactoryFactory.class).to(PathDetailsBuilderFactory.class);
            bindFactory(GraphHopperBundle.ProfileResolverFactory.class).to(ProfileResolver.class);
            bindFactory(GraphHopperBundle.GHRequestTransformerFactory.class).to(GHRequestTransformer.class);
            bindFactory(GraphHopperBundle.HasElevation.class).to(Boolean.class).named("hasElevation");
            bindFactory(GraphHopperBundle.LocationIndexFactory.class).to(LocationIndex.class);
            bindFactory(GraphHopperBundle.TranslationMapFactory.class).to(TranslationMap.class);
            bindFactory(GraphHopperBundle.EncodingManagerFactory.class).to(EncodingManager.class);
            bindFactory(GraphHopperBundle.BaseGraphFactory.class).to(BaseGraph.class);
            bindFactory(GraphHopperBundle.GtfsStorageFactory.class).to(GtfsStorage.class);
        }
    });
    environment.jersey().register(MVTResource.class);
    environment.jersey().register(NearestResource.class);
    environment.jersey().register(RouteResource.class);
    environment.jersey().register(IsochroneResource.class);
    environment.jersey().register(MapMatchingResource.class);
    if (configuration.getGraphHopperConfiguration().has("gtfs.file")) {
        // These are pt-specific implementations of /route and /isochrone, but the same API.
        // We serve them under different paths (/route-pt and /isochrone-pt), and forward
        // requests for ?vehicle=pt there.
        environment.jersey().register(new AbstractBinder() {
            @Override
            protected void configure() {
                if (configuration.getGraphHopperConfiguration().getBool("gtfs.free_walk", false)) {
                    bind(PtRouterFreeWalkImpl.class).to(PtRouter.class);
                } else {
                    bind(PtRouterImpl.class).to(PtRouter.class);
                }
            }
        });
        environment.jersey().register(PtRouteResource.class);
        environment.jersey().register(PtIsochroneResource.class);
        environment.jersey().register(PtMVTResource.class);
        environment.jersey().register(PtRedirectFilter.class);
    }
    environment.jersey().register(SPTResource.class);
    environment.jersey().register(I18NResource.class);
    environment.jersey().register(InfoResource.class);
    environment.healthChecks().register("graphhopper", new GraphHopperHealthCheck(graphHopper));
    environment.jersey().register(environment.healthChecks());
    environment.jersey().register(HealthCheckResource.class);
}

