@POST
@Consumes({ MediaType.APPLICATION_XML, "application/gpx+xml" })
@Produces({ MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML, "application/gpx+xml" })
public Response match(Gpx gpx, @Context
UriInfo uriInfo, @QueryParam(WAY_POINT_MAX_DISTANCE)
@DefaultValue("1")
double minPathPrecision, @QueryParam("type")
@DefaultValue("json")
String outType, @QueryParam(INSTRUCTIONS)
@DefaultValue("true")
boolean instructions, @QueryParam(CALC_POINTS)
@DefaultValue("true")
boolean calcPoints, @QueryParam("elevation")
@DefaultValue("false")
boolean enableElevation, @QueryParam("points_encoded")
@DefaultValue("true")
boolean pointsEncoded, @QueryParam("locale")
@DefaultValue("en")
String localeStr, @QueryParam("profile")
String profile, @QueryParam(PATH_DETAILS)
List<String> pathDetails, @QueryParam("gpx.route")
@DefaultValue("true")
boolean withRoute, @QueryParam("gpx.track")
@DefaultValue("true")
boolean withTrack, @QueryParam("traversal_keys")
@DefaultValue("false")
boolean enableTraversalKeys, @QueryParam("gps_accuracy")
@DefaultValue("40")
double gpsAccuracy) // PATH: Test should invoke the next RouteResource.initHints(...) [step in execution path]
{
    boolean writeGPX = "gpx".equalsIgnoreCase(outType);
    if (gpx.trk.isEmpty()) {
        throw new IllegalArgumentException("No tracks found in GPX document. Are you using waypoints or routes instead?");
    }
    if (gpx.trk.size() > 1) {
        throw new IllegalArgumentException("GPX documents with multiple tracks not supported yet.");
    }
    instructions = writeGPX || instructions;
    StopWatch sw = new StopWatch().start();
    PMap hints = new PMap();
    RouteResource.initHints(hints, uriInfo.getQueryParameters());
    // resolve profile and remove legacy vehicle/weighting parameters
    // we need to explicitly disable CH here because map matching does not use it
    PMap profileResolverHints = new PMap(hints);
    profileResolverHints.putObject("profile", profile);
    profileResolverHints.putObject(Parameters.CH.DISABLE, true);
    profile = profileResolver.resolveProfile(profileResolverHints);
    hints.putObject("profile", profile);
    removeLegacyParameters(hints);
    MapMatching matching = new MapMatching(graphHopper.getBaseGraph(), ((LocationIndexTree) (graphHopper.getLocationIndex())), mapMatchingRouterFactory.createMapMatchingRouter(hints));
    matching.setMeasurementErrorSigma(gpsAccuracy);
    List<Observation> measurements = GpxConversions.getEntries(gpx.trk.get(0));
    MatchResult matchResult = matching.match(measurements);
    sw.stop();
    logger.info(objectMapper.createObjectNode().put("duration", sw.getNanos()).put("profile", profile).put("observations", measurements.size()).putPOJO("mapmatching", matching.getStatistics()).toString());
    if ("extended_json".equals(outType)) {
        return Response.ok(convertToTree(matchResult, enableElevation, pointsEncoded)).header("X-GH-Took", "" + Math.round(sw.getMillisDouble())).build();
    } else {
        Translation tr = trMap.getWithFallBack(Helper.getLocale(localeStr));
        RamerDouglasPeucker simplifyAlgo = new RamerDouglasPeucker().setMaxDistance(minPathPrecision);
        PathMerger pathMerger = new PathMerger(matchResult.getGraph(), matchResult.getWeighting()).setEnableInstructions(instructions).setPathDetailsBuilders(graphHopper.getPathDetailsBuilderFactory(), pathDetails).setRamerDouglasPeucker(simplifyAlgo).setSimplifyResponse(minPathPrecision > 0);
        ResponsePath responsePath = pathMerger.doWork(PointList.EMPTY, Collections.singletonList(matchResult.getMergedPath()), graphHopper.getEncodingManager(), tr);
        // GraphHopper thinks an empty path is an invalid path, and further that an invalid path is still a path but
        // marked with a non-empty list of Exception objects. I disagree, so I clear it.
        responsePath.getErrors().clear();
        GHResponse rsp = new GHResponse();
        rsp.add(responsePath);
        if (writeGPX) {
            long time = gpx.trk.get(0).getStartTime().map(Date::getTime).orElse(System.currentTimeMillis());
            return Response.ok(GpxConversions.createGPX(rsp.getBest().getInstructions(), gpx.trk.get(0).name != null ? gpx.trk.get(0).name : "", time, enableElevation, withRoute, withTrack, false, Constants.VERSION, tr), "application/gpx+xml").header("X-GH-Took", "" + Math.round(sw.getMillisDouble())).build();
        } else {
            ObjectNode map = ResponsePathSerializer.jsonObject(rsp, osmDate, instructions, calcPoints, enableElevation, pointsEncoded, sw.getMillisDouble());
            Map<String, Object> matchStatistics = new HashMap<>();
            matchStatistics.put("distance", matchResult.getMatchLength());
            matchStatistics.put("time", matchResult.getMatchMillis());
            matchStatistics.put("original_distance", matchResult.getGpxEntriesLength());
            map.putPOJO("map_matching", matchStatistics);
            if (enableTraversalKeys) {
                List<Integer> traversalKeylist = new ArrayList<>();
                for (EdgeMatch em : matchResult.getEdgeMatches()) {
                    EdgeIteratorState edge = em.getEdgeState();
                    // encode edges as traversal keys which includes orientation, decode simply by multiplying with 0.5
                    traversalKeylist.add(edge.getEdgeKey());
                }
                map.putPOJO("traversal_keys", traversalKeylist);
            }
            return Response.ok(map).header("X-GH-Took", "" + Math.round(sw.getMillisDouble())).build();
