public Response doGet(@Context
UriInfo uriInfo, @QueryParam("profile")
String profileName, @QueryParam("buckets")
@Range(min = 1, max = 20)
@DefaultValue("1")
OptionalInt nBuckets, @QueryParam("reverse_flow")
@DefaultValue("false")
boolean reverseFlow, @QueryParam("point")
@NotNull
GHPointParam point, @QueryParam("time_limit")
@DefaultValue("600")
OptionalLong timeLimitInSeconds, @QueryParam("distance_limit")
@DefaultValue("-1")
OptionalLong distanceLimitInMeter, @QueryParam("weight_limit")
@DefaultValue("-1")
OptionalLong weightLimit, @QueryParam("type")
@DefaultValue("json")
ResponseType respType, @QueryParam("tolerance")
@DefaultValue("0")
double toleranceInMeter, @QueryParam("full_geometry")
@DefaultValue("false")
boolean fullGeometry) // PATH: Test should invoke the next RouteResource.initHints(...) [step in execution path]
{
    StopWatch sw = new StopWatch().start();
    PMap hintsMap = new PMap();
    RouteResource.initHints(hintsMap, uriInfo.getQueryParameters());
    hintsMap.putObject(Parameters.CH.DISABLE, true);
    hintsMap.putObject(Parameters.Landmark.DISABLE, true);
    PMap profileResolverHints = new PMap(hintsMap);
    profileResolverHints.putObject("profile", profileName);
    profileName = profileResolver.resolveProfile(profileResolverHints);
    removeLegacyParameters(hintsMap);
    Profile profile = graphHopper.getProfile(profileName);
