            info.put("road_data_timestamp", osmDate);
        }
        finalJson = json;
    }
    logger.info((("took: " + sw.getSeconds()) + ", visited nodes:") + shortestPathTree.getVisitedNodes());
    return Response.ok(finalJson).header("X-GH-Took", "" + (sw.getSeconds() * 1000)).build();
}

