@GET
@Path("{z}/{x}/{y}.mvt")
@Produces("application/x-protobuf")
public Response doGetXyz(@Context
HttpServletRequest httpReq, @Context
UriInfo uriInfo, @PathParam("z")
int zInfo, @PathParam("x")
int xInfo, @PathParam("y")
int yInfo, @QueryParam(Parameters.Details.PATH_DETAILS)
List<String> pathDetails) {
    Coordinate nw = num2deg(xInfo, yInfo, zInfo);
    Coordinate se = num2deg(xInfo + 1, yInfo + 1, zInfo);
    BBox bbox = new BBox(nw.x, se.x, se.y, nw.y);
    if (!bbox.isValid()) {
        throw new IllegalStateException("Invalid bbox " + bbox);
    }
    VectorTileEncoder vectorTileEncoder = new VectorTileEncoder();
    // 256x256 pixels per MVT. here we transform from the global coordinate system to the local one of the tile.
    AffineTransformation affineTransformation = new AffineTransformation();
    affineTransformation.translate(-nw.x, -se.y);
    affineTransformation.scale(256.0 / (se.x - nw.x), (-256.0) / (nw.y - se.y));
    affineTransformation.translate(0, 256);
    gtfsStorage.getStopIndex().query(bbox, edgeId -> {
        for (PtGraph.PtEdge ptEdge : gtfsStorage.getPtGraph().backEdgesAround(edgeId)) {
            if (ptEdge.getType() == GtfsStorage.EdgeType.EXIT_PT) {
                GtfsStorage.PlatformDescriptor fromPlatformDescriptor = ptEdge.getAttrs().platformDescriptor;
                Stop stop = gtfsStorage.getGtfsFeeds().get(fromPlatformDescriptor.feed_id).stops.get(fromPlatformDescriptor.stop_id);
                Map<String, Object> properties = new HashMap<>(2);
                properties.put("feed_id", fromPlatformDescriptor.feed_id);
                properties.put("stop_id", fromPlatformDescriptor.stop_id);
                Point feature = geometryFactory.createPoint(new Coordinate(stop.stop_lon, stop.stop_lat));
                feature.setUserData(properties);
                Geometry g = affineTransformation.transform(feature);
                vectorTileEncoder.addFeature("stops", properties, g);
            }
        }
    });
    return // PATH: Test should invoke the next VectorTileEncoder.encode(...) [step in execution path]
    Response.ok(vectorTileEncoder.encode(), PBF).build();
}

/**
 *
 * @return a byte array with the vector tile
 */
public byte[] encode() {
    VectorTile.Tile.Builder tile = VectorTile.Tile.newBuilder();
    for (Map.Entry<String, Layer> e : layers.entrySet()) {
        String layerName = e.getKey();
        Layer layer = e.getValue();
        VectorTile.Tile.Layer.Builder tileLayer = VectorTile.Tile.Layer.newBuilder();
        tileLayer.setVersion(2);
        tileLayer.setName(layerName);
        tileLayer.addAllKeys(layer.keys());
        for (Object value : layer.values()) {
            VectorTile.Tile.Value.Builder tileValue = VectorTile.Tile.Value.newBuilder();
            if (value instanceof String) {
                tileValue.setStringValue(((String) (value)));
            } else if (value instanceof Integer) {
                tileValue.setSintValue(((Integer) (value)).intValue());
            } else if (value instanceof Long) {
                tileValue.setSintValue(((Long) (value)).longValue());
            } else if (value instanceof Float) {
                tileValue.setFloatValue(((Float) (value)).floatValue());
            } else if (value instanceof Double) {
                tileValue.setDoubleValue(((Double) (value)).doubleValue());
            } else if (value instanceof BigDecimal) {
                tileValue.setStringValue(value.toString());
            } else if (value instanceof Number) {
                tileValue.setDoubleValue(((Number) (value)).doubleValue());
            } else if (value instanceof Boolean) {
                tileValue.setBoolValue(((Boolean) (value)).booleanValue());
            } else {
                tileValue.setStringValue(value.toString());
            }
            tileLayer.addValues(tileValue.build());
        }
        tileLayer.setExtent(extent);
        for (Feature feature : layer.features) {
            Geometry geometry = feature.geometry;
            VectorTile.Tile.Feature.Builder featureBuilder = VectorTile.Tile.Feature.newBuilder();
            featureBuilder.addAllTags(feature.tags);
            if (feature.id >= 0) {
                featureBuilder.setId(feature.id);
            }
            GeomType geomType = toGeomType(geometry);
            x = 0;
            y = 0;
            List<Integer> commands = commands(geometry);
            // skip features with no geometry commands
            if (commands.isEmpty()) {
                continue;
            }
            // Extra step to parse and check validity and try to repair. Probably expensive.
            if ((simplificationDistanceTolerance > 0.0) && (geomType == GeomType.POLYGON)) {
                double scale = (autoScale) ? extent / 256.0 : 1.0;
                Geometry decodedGeometry = VectorTileDecoder.decodeGeometry(gf, geomType, commands, scale);
                if (!isValid(decodedGeometry)) {
                    // Invalid. Try more simplification and without preserving topology.
