                lineString = pl.toLineString(false);
            } else if ((((rc == RoadClass.MOTORWAY) || ((zInfo > 10) && ((rc == RoadClass.PRIMARY) || (rc == RoadClass.TRUNK)))) || ((zInfo > 11) && (rc == RoadClass.SECONDARY))) || (zInfo > 12)) {
                double lat = na.getLat(edge.getBaseNode());
