            if (ev instanceof EnumEncodedValue) {
                map.put(ev.getName(), edge.get(((EnumEncodedValue) (ev))).toString() + (ev.isStoreTwoDirections() ? " | " + edge.getReverse(((EnumEncodedValue) (ev))).toString() : ""));
            } else if (ev instanceof DecimalEncodedValue) {
