    // and clipping in the no.ecc code? https://github.com/graphhopper/graphhopper/commit/0f96c2deddb24efa97109e35e0c05f1c91221f59#r90830001
    VectorTileEncoder vectorTileEncoder = new VectorTileEncoder();
