            } else if (ev instanceof BooleanEncodedValue) {
                map.put(ev.getName(), edge.get(((BooleanEncodedValue) (ev))) + (ev.isStoreTwoDirections() ? " | " + edge.getReverse(((BooleanEncodedValue) (ev))) : ""));
